"""Configure Langfuse tracing from ``endpoints.yml`` or ``integrations.yml``.

Loads Langfuse settings, validates ``${VAR}`` key references, sets
``LANGFUSE_*`` environment variables, and registers the LiteLLM Langfuse
callback. Mantle projects prefer ``integrations.yml``; legacy CALM projects
use ``endpoints.yml``.
"""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Any, Dict, List, Mapping, Optional, Text, Union

import structlog

from rasa.shared.constants import SECRET_DATA_FORMAT_PATTERN
from rasa.shared.exceptions import RasaException
from rasa.shared.utils.io import resolve_environment_variables
from rasa.shared.utils.yaml import read_config_file
from rasa.tracing.constants import (
    ENDPOINTS_TRACING_KEY,
    LANGFUSE_CONFIG_BASE_URL_KEY,
    LANGFUSE_CONFIG_DEBUG_KEY,
    LANGFUSE_CONFIG_ENVIRONMENT_KEY,
    LANGFUSE_CONFIG_MEDIA_UPLOAD_THREAD_COUNT_KEY,
    LANGFUSE_CONFIG_PRIVATE_KEY,
    LANGFUSE_CONFIG_PUBLIC_KEY,
    LANGFUSE_CONFIG_RELEASE_KEY,
    LANGFUSE_CONFIG_SAMPLE_RATE_KEY,
    LANGFUSE_CONFIG_TIMEOUT_KEY,
    LANGFUSE_ENV_VAR_DEBUG,
    LANGFUSE_ENV_VAR_HOST,
    LANGFUSE_ENV_VAR_MEDIA_UPLOAD_THREAD_COUNT,
    LANGFUSE_ENV_VAR_OTEL_HOST,
    LANGFUSE_ENV_VAR_PUBLIC_KEY,
    LANGFUSE_ENV_VAR_RELEASE,
    LANGFUSE_ENV_VAR_SAMPLE_RATE,
    LANGFUSE_ENV_VAR_SECRET_KEY,
    LANGFUSE_ENV_VAR_TIMEOUT,
    LANGFUSE_ENV_VAR_TRACING_ENVIRONMENT,
    LITELLM_ENV_VAR_USE_OTEL_REQUEST_SPAN,
    TRACING_TYPE_LANGFUSE,
)
from rasa.tracing.exceptions import (
    DuplicateTracingConfigException,
    InvalidLangfuseConfigException,
)
from rasa.utils.endpoints import EndpointConfig

structlogger = structlog.get_logger()

_LANGFUSE_CONFIG_NOT_FOUND = "langfuse_configuration.langfuse_config_not_found"

# https://langfuse.com/docs/observability/features/environments#data-model
LANGFUSE_VALID_ENVIRONMENT_PATTERN = re.compile(r"^(?!langfuse)[a-z0-9-_]+$")

_LANGFUSE_CONFIG_VALUE_KEYS = (
    LANGFUSE_CONFIG_PUBLIC_KEY,
    LANGFUSE_CONFIG_PRIVATE_KEY,
    LANGFUSE_CONFIG_BASE_URL_KEY,
    LANGFUSE_CONFIG_TIMEOUT_KEY,
    LANGFUSE_CONFIG_DEBUG_KEY,
    LANGFUSE_CONFIG_ENVIRONMENT_KEY,
    LANGFUSE_CONFIG_RELEASE_KEY,
    LANGFUSE_CONFIG_MEDIA_UPLOAD_THREAD_COUNT_KEY,
    LANGFUSE_CONFIG_SAMPLE_RATE_KEY,
)


def configure_langfuse(
    endpoints_file: str, langfuse_environment_name: Optional[str] = None
) -> None:
    """Configure Langfuse callback for litellm from endpoints file.

    Args:
        endpoints_file: Path to endpoints configuration file.
        langfuse_environment_name: Optional environment name to force for Langfuse
            tracing (e.g. "E2E test", "DU test"). If provided, this overrides
            any environment configured in the endpoints file.
    """
    langfuse_config = _get_langfuse_config(endpoints_file)

    if not langfuse_config:
        structlogger.debug(
            _LANGFUSE_CONFIG_NOT_FOUND,
            event_info=(
                f"No Langfuse configuration found in {endpoints_file}, "
                f"Langfuse will not be configured."
            ),
        )
        return

    configure_langfuse_from_config(
        langfuse_config.kwargs,
        source=endpoints_file,
        langfuse_environment_name=langfuse_environment_name,
    )


def configure_langfuse_from_config(
    config: Mapping[str, Any],
    *,
    source: str,
    langfuse_environment_name: Optional[str] = None,
) -> None:
    """Configure Langfuse from an already-parsed config mapping.

    Shared apply path for endpoints.yml and integrations.yml Langfuse blocks.
    Validates keys, sets ``LANGFUSE_*`` environment variables, and registers the
    LiteLLM Langfuse callback.

    Args:
        config: Mapping with Langfuse keys (``public_key``, ``private_key``,
            ``host``, and optional knobs). Typically
            ``EndpointConfig.kwargs`` or
            ``LangfuseTracingSettings.as_config_dict()``.
        source: Human-readable origin used in log messages (e.g. file path).
        langfuse_environment_name: Optional environment name to force for
            Langfuse tracing (e.g. ``"e2e-test"``). Overrides any ``environment``
            value in *config* when provided.
    """
    if not _is_langfuse_available():
        return

    config_values = _config_values_from_mapping(config)
    _validate_langfuse_config(config_values)

    public_key = config_values[LANGFUSE_CONFIG_PUBLIC_KEY]
    private_key = config_values[LANGFUSE_CONFIG_PRIVATE_KEY]

    resolved_keys = _resolve_environment_variables(public_key, private_key)
    _set_langfuse_environment_variables(
        config_values,
        resolved_keys,
        langfuse_environment_name=langfuse_environment_name,
    )
    _configure_litellm_callback()

    structlogger.info(
        "langfuse_configuration.langfuse_config_configured",
        event_info=f"Langfuse has been configured from {source}.",
    )


def configure_langfuse_for_project(
    endpoints_file: Optional[str] = None,
    *,
    project_root: str | Path | None = None,
    is_mantle: Optional[bool] = None,
    langfuse_environment_name: Optional[str] = None,
) -> None:
    """Configure Langfuse from ``integrations.yml`` (Mantle) or endpoints (CALM).

    Callers pass *is_mantle* when they have already resolved the engine
    (``configure_commandline`` does, from model metadata or layout). Otherwise
    the on-disk layout decides: at least two of ``agent.yml``,
    ``integrations.yml``, and ``skills/*/skill.md`` (see
    :func:`~rasa.shared.project_structure.has_mantle_project_layout`). A CALM
    project that carries a stray ``integrations.yml`` but no second Mantle
    marker reads Langfuse from ``endpoints.yml``, exactly as if the file were
    absent.

    Mantle contexts read only the Langfuse entry of ``tracing:`` in
    ``integrations.yml``; *endpoints_file* is never consulted. An invalid
    ``tracing:`` block is logged and leaves Langfuse off instead of aborting
    the command.

    Args:
        endpoints_file: Path to endpoints configuration, or ``None`` when the
            command has no ``--endpoints``. Ignored for Mantle contexts.
        project_root: Project directory used to locate ``integrations.yml``.
            Defaults to the current working directory.
        is_mantle: Whether the CLI context is Mantle, as resolved by the caller
            (see :func:`~rasa.shared.engine_version.is_mantle_cli_context`).
            ``None`` falls back to the on-disk project layout.
        langfuse_environment_name: Optional environment name override passed
            through to the apply path (e.g. ``"e2e-test"``).
    """
    from rasa.shared.project_structure import (
        MANTLE_INTEGRATIONS_FILE,
        has_mantle_project_layout,
    )

    root = Path(project_root) if project_root is not None else Path.cwd()
    if is_mantle is None:
        is_mantle = has_mantle_project_layout(root)

    if is_mantle:
        integration_file = root / MANTLE_INTEGRATIONS_FILE
        integration_config = _integration_langfuse_config(integration_file, root)
        if integration_config is None:
            structlogger.debug(
                _LANGFUSE_CONFIG_NOT_FOUND,
                event_info=(
                    f"No Langfuse configuration found in {integration_file}, "
                    "Langfuse will not be configured."
                ),
            )
            return
        configure_langfuse_from_config(
            integration_config,
            source=str(integration_file),
            langfuse_environment_name=langfuse_environment_name,
        )
        return

    if not endpoints_file:
        structlogger.debug(
            _LANGFUSE_CONFIG_NOT_FOUND,
            event_info=(
                "No endpoints file was provided, Langfuse will not be configured."
            ),
        )
        return

    endpoints_config = _get_langfuse_config(endpoints_file)
    if endpoints_config is None:
        structlogger.debug(
            _LANGFUSE_CONFIG_NOT_FOUND,
            event_info=(
                f"No Langfuse configuration found in {endpoints_file}, "
                "Langfuse will not be configured."
            ),
        )
        return
    configure_langfuse_from_config(
        endpoints_config.kwargs,
        source=str(endpoints_file),
        langfuse_environment_name=langfuse_environment_name,
    )


def _integration_langfuse_config(
    integration_file: Path, project_root: Path
) -> Optional[Dict[str, Any]]:
    """Return the Langfuse entry of ``tracing:`` in ``integrations.yml``, if any.

    Only called for a confirmed Mantle context. ``integrations.yml`` can still
    be missing when ``agent.yml`` and a ``skill.md`` are the two markers that
    selected Mantle, or when the caller resolved Mantle from model metadata.
    The ``is_file`` guard below returns ``None`` in that case.

    A malformed ``tracing:`` block is logged here rather than raised, so the
    command keeps running with Langfuse off.
    """
    if not integration_file.is_file():
        return None

    # Imported lazily so runs without a Mantle project never pull in mantle.
    from rasa.mantle.config.tracing import load_integration_tracing

    try:
        settings = load_integration_tracing(project_root, tracer="langfuse")
    except RasaException as error:
        structlogger.error(
            "langfuse_configuration.integration_tracing_invalid",
            event_info=(
                f"Invalid 'tracing:' configuration in {integration_file}: "
                f"{error} Langfuse will not be configured."
            ),
        )
        return None
    if settings is None or settings.langfuse is None:
        return None
    return settings.langfuse.as_config_dict()


def _is_langfuse_available() -> bool:
    """Check if Langfuse is available."""
    from rasa.builder.telemetry.langfuse_integration.langfuse_compat import (
        is_langfuse_available,
    )

    if not is_langfuse_available():
        structlogger.error(
            "langfuse_configuration.langfuse_not_available",
            event_info=(
                "Langfuse is not available. "
                "Please install langfuse via `pip install rasa-pro[monitoring]`. "
                "Langfuse will not be configured."
            ),
        )
        return False
    return True


def _get_langfuse_config(endpoints_file: str) -> Optional[EndpointConfig]:
    """Read Langfuse configuration from endpoints file."""
    if not endpoints_file:
        return None

    try:
        content = read_config_file(endpoints_file)
    except FileNotFoundError:
        structlogger.debug(
            "langfuse_configuration.endpoints_file_not_found",
            event_info=(
                f"Endpoints file not found: {endpoints_file}, "
                f"Langfuse will not be configured."
            ),
        )
        return None
    except Exception:
        structlogger.error(
            "langfuse_configuration.endpoints_file_read_error",
            event_info=(
                f"Error reading endpoints file: {endpoints_file}, "
                f"Langfuse will not be configured."
            ),
        )
        return None

    if content.get(ENDPOINTS_TRACING_KEY) is None:
        return None

    tracing_config: Union[List[Dict[Text, Any]], Dict[Text, Any]] = content.get(
        ENDPOINTS_TRACING_KEY, []
    )

    tracing_configs = _parse_tracing_configs(tracing_config)

    langfuse_configs = [
        config for config in tracing_configs if config.type == TRACING_TYPE_LANGFUSE
    ]

    if len(langfuse_configs) == 0:
        return None

    if len(langfuse_configs) > 1:
        _log_multiple_langfuse_configs_error(endpoints_file)
        raise DuplicateTracingConfigException(
            f"Multiple Langfuse configs found in {endpoints_file}, "
            "which is not supported. Only one Langfuse config is allowed."
        )

    return langfuse_configs[0]


def _parse_tracing_configs(
    tracing_config: Union[List[Dict[Text, Any]], Dict[Text, Any]],
) -> List[EndpointConfig]:
    """Parse tracing configuration into list of EndpointConfig objects."""
    if isinstance(tracing_config, list):
        return [EndpointConfig.from_dict(item) for item in tracing_config]
    else:
        return [EndpointConfig.from_dict(tracing_config)]


def _log_multiple_langfuse_configs_error(endpoints_file: str) -> None:
    """Log error when multiple Langfuse configs are found."""
    structlogger.error(
        "langfuse_configuration.multiple_langfuse_configs",
        event_info=(
            f"Multiple Langfuse configs found in {endpoints_file}, "
            f"which is not supported. Only one Langfuse config is allowed."
        ),
    )


def _extract_langfuse_config_values(
    langfuse_config: EndpointConfig,
) -> Dict[str, Any]:
    """Extract all configuration values from Langfuse EndpointConfig."""
    return _config_values_from_mapping(langfuse_config.kwargs)


def _config_values_from_mapping(config: Mapping[str, Any]) -> Dict[str, Any]:
    """Normalize a Langfuse config mapping to the apply-path value dict."""
    return {key: config.get(key) for key in _LANGFUSE_CONFIG_VALUE_KEYS}


def _resolve_environment_variables(
    public_key: str, private_key: str
) -> Dict[str, Union[str, List[Any], Dict[str, Any]]]:
    """Resolve environment variables in public and secret keys."""
    return {
        LANGFUSE_CONFIG_PUBLIC_KEY: resolve_environment_variables(public_key),
        LANGFUSE_CONFIG_PRIVATE_KEY: resolve_environment_variables(private_key),
    }


def _set_langfuse_environment_variables(
    config_values: Dict[str, Any],
    resolved_keys: Dict[str, Optional[str]],
    langfuse_environment_name: Optional[str] = None,
) -> None:
    """Set Langfuse environment variables for LiteLLM integration.

    Logs warnings when overwriting existing environment variables.
    """
    # Map of config keys to (source dict, environment variable name)
    env_var_mappings = [
        (LANGFUSE_CONFIG_PUBLIC_KEY, resolved_keys, LANGFUSE_ENV_VAR_PUBLIC_KEY),
        (LANGFUSE_CONFIG_PRIVATE_KEY, resolved_keys, LANGFUSE_ENV_VAR_SECRET_KEY),
        # The configured host feeds two independent Langfuse code paths, so it is
        # mapped to two env vars: LANGFUSE_OTEL_HOST for litellm's OTEL exporter,
        # and LANGFUSE_HOST for the standalone langfuse SDK client used in
        # langfuse_telemetry.py (which ignores LANGFUSE_OTEL_HOST and otherwise
        # falls back to the hardcoded https://cloud.langfuse.com). See ENG-3041.
        (LANGFUSE_CONFIG_BASE_URL_KEY, config_values, LANGFUSE_ENV_VAR_OTEL_HOST),
        (LANGFUSE_CONFIG_BASE_URL_KEY, config_values, LANGFUSE_ENV_VAR_HOST),
        (LANGFUSE_CONFIG_TIMEOUT_KEY, config_values, LANGFUSE_ENV_VAR_TIMEOUT),
        (LANGFUSE_CONFIG_DEBUG_KEY, config_values, LANGFUSE_ENV_VAR_DEBUG),
        (LANGFUSE_CONFIG_RELEASE_KEY, config_values, LANGFUSE_ENV_VAR_RELEASE),
        (
            LANGFUSE_CONFIG_MEDIA_UPLOAD_THREAD_COUNT_KEY,
            config_values,
            LANGFUSE_ENV_VAR_MEDIA_UPLOAD_THREAD_COUNT,
        ),
        (LANGFUSE_CONFIG_SAMPLE_RATE_KEY, config_values, LANGFUSE_ENV_VAR_SAMPLE_RATE),
    ]

    def _set_env_var(env_var_name: str, value: Optional[Any]) -> None:
        if value is None:
            return
        # Endpoints YAML parses bare scalars to native Python types (e.g.
        # `debug: true` -> bool, `timeout: 30` -> int, `sample_rate: 0.5` ->
        # float), but os.environ only accepts str. Coerce here so the documented
        # unquoted syntax works without a TypeError. Booleans are lowercased so
        # they match what Langfuse/LiteLLM expect (and the quoted "true"/"false"
        # workaround) rather than Python's capitalized str(True) == "True".
        string_value = str(value).lower() if isinstance(value, bool) else str(value)
        existing_value = os.getenv(env_var_name)
        # Only warn when the value is actually changing to reduce log noise
        if existing_value is not None and existing_value != string_value:
            structlogger.warning(
                "langfuse_configuration.overwriting_env_var",
                event_info=(
                    f"Overwriting existing environment variable '{env_var_name}' "
                    f"with value from Langfuse configuration."
                ),
                env_var_name=env_var_name,
            )
        os.environ[env_var_name] = string_value

    for config_key, source_dict, env_var_name in env_var_mappings:
        _set_env_var(env_var_name, source_dict.get(config_key))

    # Decide langfuse environment name value once, then set
    environment = (
        langfuse_environment_name
        if langfuse_environment_name is not None
        else config_values.get(LANGFUSE_CONFIG_ENVIRONMENT_KEY)
    )
    _set_env_var(LANGFUSE_ENV_VAR_TRACING_ENVIRONMENT, environment)


def _configure_litellm_callback() -> None:
    """Configure LiteLLM to use Langfuse as a callback."""
    import litellm

    from rasa.tracing.rasa_langfuse_otel_logger import build_rasa_langfuse_otel_logger

    # LiteLLM will automatically trace LLM calls to langfuse if these environment
    # variables are set and the callback is configured. We pass a Rasa-owned
    # LangfuseOtelLogger subclass so assistant text is not dropped when tool
    # calls are present (see rasa.tracing.rasa_langfuse_otel_logger).
    #
    # Async completions use ``litellm._async_success_callback``; string callbacks
    # are duplicated there by LiteLLM during ``function_setup``, but a concrete
    # logger instance must be registered on both lists explicitly.
    _logger = build_rasa_langfuse_otel_logger()
    litellm.success_callback = [_logger]
    litellm._async_success_callback = [_logger]

    # Force LiteLLM to emit its own populated LLM request span. As of litellm
    # 1.87.0 it skips that span whenever a parent OTEL span is active and stamps
    # attributes onto the parent instead. Rasa's command generator always runs
    # inside an ``@observe(capture_input=False, capture_output=False)`` parent,
    # so without this the Input/Output are dropped (ENG-2929). Set on the process
    # environment so it overrides an inherited value (there is no legitimate
    # reason to run Langfuse tracing with this disabled).
    os.environ[LITELLM_ENV_VAR_USE_OTEL_REQUEST_SPAN] = "true"
    structlogger.debug(
        "langfuse_configuration.forcing_litellm_request_span",
        event_info=(
            f"Set '{LITELLM_ENV_VAR_USE_OTEL_REQUEST_SPAN}=true' so LiteLLM emits "
            f"a populated LLM request span under Rasa's tracing spans."
        ),
    )


def validate_langfuse_config_mapping(config: Mapping[str, Any]) -> None:
    """Validate a Langfuse config mapping.

    Checks required keys, ``${VAR}`` syntax for public/private keys, and the
    optional environment name. Shared by the apply path and train-time
    ``integrations.yml`` validation.

    Args:
        config: Mapping with Langfuse keys (``public_key``, ``private_key``,
            ``host``, and optional knobs).

    Raises:
        InvalidLangfuseConfigException: If the mapping fails validation.
    """
    _validate_langfuse_config(_config_values_from_mapping(config))


def _validate_langfuse_config(config_values: Dict[str, Any]) -> None:
    """Validate Langfuse configuration."""
    _validate_required_keys(
        config_values,
        [
            LANGFUSE_CONFIG_PUBLIC_KEY,
            LANGFUSE_CONFIG_PRIVATE_KEY,
            LANGFUSE_CONFIG_BASE_URL_KEY,
        ],
    )

    public_key = config_values[LANGFUSE_CONFIG_PUBLIC_KEY]
    private_key = config_values[LANGFUSE_CONFIG_PRIVATE_KEY]
    _validate_key_syntax(public_key, private_key)
    _validate_environment_name(config_values.get(LANGFUSE_CONFIG_ENVIRONMENT_KEY))


def _validate_environment_name(environment: Optional[str]) -> None:
    """Validate the optional Langfuse environment name if provided.

    The environment must match the regex ^(?!langfuse)[a-z0-9-_]+$ and be at most
    40 characters long.
    """
    if not environment:
        return

    if (
        not isinstance(environment, str)
        or len(environment) > 40
        or not LANGFUSE_VALID_ENVIRONMENT_PATTERN.match(environment)
    ):
        error_message = (
            f"Invalid Langfuse environment: '{environment}'. It can only contain "
            f"lowercase letters, numbers, hyphens, and underscores. It cannot start "
            f"with 'langfuse' prefix and must be at most 40 characters long."
        )
        structlogger.error(
            "langfuse_configuration.invalid_environment",
            event_info=error_message,
            environment=environment,
        )
        raise InvalidLangfuseConfigException(error_message)


def _validate_required_keys(
    config_values: Dict[str, Any], required_keys: List[str]
) -> None:
    """Validate that required keys are provided."""
    missing_keys: List[str] = []
    for key in required_keys:
        if not config_values[key]:
            missing_keys.append(key)

    if missing_keys:
        structlogger.error(
            "tracing.langfuse_config.invalid_config",
            event_info=(
                f"Langfuse config is invalid. The following keys are required and "
                f"currently not configured: {missing_keys}."
            ),
        )
        raise InvalidLangfuseConfigException(
            f"Langfuse config is invalid. The following keys are required and "
            f"currently not configured: {missing_keys}."
        )


def _validate_key_syntax(public_key: str, secret_key: str) -> None:
    """Validate that keys use the correct ${VAR} syntax for environment variables."""
    if not re.match(SECRET_DATA_FORMAT_PATTERN, public_key) or not re.match(
        SECRET_DATA_FORMAT_PATTERN, secret_key
    ):
        structlogger.error(
            "langfuse_configuration.langfuse_config_invalid",
            event_info=(
                f"Langfuse config is invalid: {LANGFUSE_CONFIG_PUBLIC_KEY} and "
                f"{LANGFUSE_CONFIG_PRIVATE_KEY} need to be provided via the "
                f"${{syntax}}."
            ),
        )
        raise InvalidLangfuseConfigException(
            f"Langfuse config is invalid: {LANGFUSE_CONFIG_PUBLIC_KEY} and "
            f"{LANGFUSE_CONFIG_PRIVATE_KEY} need to be provided via the ${{syntax}}."
        )
